 $('weeklyMissions').innerHTML=missions.map(m=>{let p=missionProgress(m),done=p>=m.target,claimed=!!data.weeklyMissionClaims?.[key]?.[m.id];return `<article class="weekly-mission ${done?'done':''}"><div class="weekly-mission-top"><div><strong>${escapeHabit(m.title)}</strong><small>${escapeHabit(m.desc)}</small></div><b>${done?'완료':p+' / '+m.target}</b></div><div class="mission-track"><i style="width:${Math.min(100,p/m.target*100)}%"></i></div><span class="mission-reward">${claimed?'✓ 보상 획득':'🔥 +'+m.reward+' XP'}</span></article>`}).join('');
