function switchTab(t){document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active',s.id===t));window.scrollTo({top:0,left:0,behavior:'auto'});document.querySelector('main')?.scrollTo({top:0,left:0,behavior:'auto'});document.querySelectorAll('.screen').forEach(s=>{if(s.id===t){s.scrollTop=0;s.querySelectorAll('[data-scroll-region]').forEach(x=>x.scrollTop=0)}});if(t==='home')renderHome();if(t==='workout')renderHistory();if(t==='diet')renderDiet();if(t==='habit')renderHabits();if(t==='report')renderReport()}
